const reports = [
  { src: 'forum', text: 'Agent loops forever calling the same tool', sev: 4, age_days: 2, votes: 61 },
  { src: 'github', text: 'AI Agent repeats tool call until timeout', sev: 4, age_days: 9, votes: 34 },
  { src: 'forum', text: 'Same tool called over and over, burns my credits', sev: 5, age_days: 1, votes: 88 },
  { src: 'forum', text: 'Model returns text not JSON and node crashes', sev: 3, age_days: 4, votes: 45 },
  { src: 'github', text: 'Structured output parser fails on markdown fences', sev: 3, age_days: 30, votes: 22 },
  { src: 'discord', text: 'Cannot tell why the agent chose that tool', sev: 2, age_days: 6, votes: 71 },
  { src: 'forum', text: 'No way to see the reasoning behind a tool choice', sev: 2, age_days: 14, votes: 39 },
  { src: 'github', text: 'Credentials leaked into the execution log', sev: 5, age_days: 3, votes: 12 },
  { src: 'forum', text: 'My OpenAI bill tripled overnight and I cannot see why', sev: 4, age_days: 5, votes: 57 }
];
return [{ json: { reports: reports, window: 'last 30 days' } }];

const d = $input.first().json;
const themes = [
  { theme: 'Agent loops on the same tool until it burns budget', match: ['loop','over and over','repeats'] },
  { theme: 'Model returns prose where the workflow expects JSON', match: ['not json','markdown fences','parser'] },
  { theme: 'No visibility into why a tool was chosen', match: ['why the agent','reasoning'] },
  { theme: 'Secrets and prompt bodies reaching the execution log', match: ['leaked','log'] },
  { theme: 'Spend moves without an explanation', match: ['bill','credits'] }
];
const out = themes.map(function (t) {
  const hits = d.reports.filter(function (r) {
    const s = r.text.toLowerCase();
    return t.match.some(function (m) { return s.indexOf(m) !== -1; });
  });
  const votes = hits.reduce(function (a, r) { return a + r.votes; }, 0);
  const sev = hits.length ? hits.reduce(function (a, r) { return a + r.sev; }, 0) / hits.length : 0;
  const recency = hits.length ? hits.reduce(function (a, r) { return a + Math.max(0, 1 - r.age_days / 30); }, 0) / hits.length : 0;
  const sources = hits.map(function (r) { return r.src; });
  const distinct = sources.filter(function (v, i) { return sources.indexOf(v) === i; });
  return { theme: t.theme, reports: hits.length, votes: votes, avg_severity: Number(sev.toFixed(1)),
    recency: Number(recency.toFixed(2)), sources: distinct.length,
    pressure: Number((hits.length * sev * (1 + recency) * (1 + (distinct.length - 1) * 0.5)).toFixed(1)) };
}).filter(function (t) { return t.reports > 0; })
  .sort(function (a, b) { return b.pressure - a.pressure; });
return [{ json: { failure_modes: out } }];

const d = $input.first().json;
const owners = {
  'Agent loops on the same tool until it burns budget': 'AI Trust - guardrails and reliability',
  'Model returns prose where the workflow expects JSON': 'AI Trust - evals and output contracts',
  'No visibility into why a tool was chosen': 'AI Trust - traces and observability',
  'Secrets and prompt bodies reaching the execution log': 'AI Trust - guardrails',
  'Spend moves without an explanation': 'AI Trust - cost'
};
const top = d.failure_modes.slice(0, 5).map(function (f, i) {
  return { rank: i + 1, theme: f.theme, pressure: f.pressure, reports: f.reports, votes: f.votes,
    cross_source: f.sources > 1, owner: owners[f.theme] || 'unassigned' };
});
const lead = top[0];
const crossSource = top.filter(function (t) { return t.cross_source; });
const say = 'Ranked by pressure - reports x severity, weighted for recency and for showing up in more than one place. ' +
  'This week the top failure mode is: ' + lead.theme + ' (' + lead.reports + ' reports, ' + lead.votes + ' votes). ' +
  crossSource.length + ' of the top ' + top.length + ' appear on more than one channel, which is the signal that separates a real defect from one loud user. ' +
  'The ranking logic is the point. This run scores seeded example reports, not live community data.';
return [{ json: { plain_english: say, top_five: top, lead_theme: lead.theme, cross_source_count: crossSource.length, actionable: crossSource.length > 0 } }];
